import { uid } from "../shared/types";
import type { Vfs } from "../vfs/types";
import type { TextDocument } from "../editor/document";

export type ChatRole = "user" | "assistant" | "system";

export type ChatMessage = {
  id: string;
  role: ChatRole;
  text: string;
  at: number;
};

export type ContextBundle = {
  activePath?: string;
  selectedText: string;
  openPaths: string[];
};

export interface ModelTransport {
  send(input: string, context: ContextBundle, onDelta: (text: string) => void, signal: AbortSignal): Promise<void>;
}

export class LocalAssistantTransport implements ModelTransport {
  async send(input: string, context: ContextBundle, onDelta: (text: string) => void, signal: AbortSignal): Promise<void> {
    const lines = [
      `I received: ${input.trim() || "(empty message)"}`,
      context.activePath ? `Active file: ${context.activePath}` : "No active file.",
      context.selectedText ? `Selection length: ${context.selectedText.length} characters.` : "No selected text.",
      "I can inspect files, search the virtual workspace, and propose edits once you ask for a concrete change."
    ];
    for (const part of lines.join("\n").match(/.{1,24}|\n/g) ?? []) {
      if (signal.aborted) return;
      onDelta(part);
      await new Promise((resolve) => setTimeout(resolve, 8));
    }
  }
}

export class OpenAIResponsesTransport implements ModelTransport {
  constructor(private readonly apiKey: string, private readonly model = "gpt-5.5") {}

  async send(input: string, context: ContextBundle, onDelta: (text: string) => void, signal: AbortSignal): Promise<void> {
    const response = await fetch("https://api.openai.com/v1/responses", {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        Authorization: `Bearer ${this.apiKey}`
      },
      body: JSON.stringify({
        model: this.model,
        instructions: "You are an assistant inside a browser code editor. Be concise and refer to provided context.",
        input: [{
          role: "user",
          content: [{
            type: "input_text",
            text: `${input}\n\nContext:\n${JSON.stringify(context, null, 2)}`
          }]
        }],
        stream: true,
        store: false
      }),
      signal
    });
    if (!response.ok || !response.body) throw new Error(`OpenAI request failed: ${response.status}`);
    await parseResponsesStream(response.body, onDelta, signal);
  }
}

export class ChatHarness {
  readonly messages: ChatMessage[] = [
    {
      id: uid("msg"),
      role: "system",
      text: "Chat is running locally by default. Configure an OpenAI key in localStorage as slug.openaiKey to use Responses API transport.",
      at: Date.now()
    }
  ];
  private abortController: AbortController | null = null;

  constructor(private readonly vfs: Vfs) {}

  get running(): boolean {
    return this.abortController !== null;
  }

  cancel(): void {
    this.abortController?.abort();
  }

  async send(input: string, activeDoc: TextDocument | undefined, openDocs: TextDocument[]): Promise<void> {
    if (!input.trim() || this.running) return;
    const context: ContextBundle = {
      selectedText: activeDoc?.selectedText() ?? "",
      openPaths: openDocs.map((doc) => doc.path ?? "(untitled)")
    };
    if (activeDoc?.path) context.activePath = activeDoc.path;
    this.messages.push({ id: uid("msg"), role: "user", text: input, at: Date.now() });
    const assistant: ChatMessage = { id: uid("msg"), role: "assistant", text: "", at: Date.now() };
    this.messages.push(assistant);
    const key = localStorage.getItem("slug.openaiKey")?.trim();
    const transport: ModelTransport = key ? new OpenAIResponsesTransport(key) : new LocalAssistantTransport();
    const controller = new AbortController();
    this.abortController = controller;
    try {
      await transport.send(input, context, (text) => {
        assistant.text += text;
      }, controller.signal);
    } catch (error) {
      assistant.text += `\nRequest failed: ${error instanceof Error ? error.message : String(error)}`;
    } finally {
      this.abortController = null;
      await this.persist();
    }
  }

  async persist(): Promise<void> {
    await this.vfs.writeFile("/.slug-chat.json", JSON.stringify(this.messages, null, 2), "application/json");
  }
}

async function parseResponsesStream(stream: ReadableStream<Uint8Array>, onDelta: (text: string) => void, signal: AbortSignal): Promise<void> {
  const reader = stream.getReader();
  const decoder = new TextDecoder();
  let buffer = "";
  while (!signal.aborted) {
    const { done, value } = await reader.read();
    if (done) break;
    buffer += decoder.decode(value, { stream: true });
    let idx: number;
    while ((idx = buffer.indexOf("\n\n")) >= 0) {
      const raw = buffer.slice(0, idx);
      buffer = buffer.slice(idx + 2);
      const data = raw.split("\n").filter((line) => line.startsWith("data:")).map((line) => line.slice(5).trim()).join("\n");
      if (!data || data === "[DONE]") continue;
      const parsed = JSON.parse(data) as { type?: string; delta?: string; text?: string };
      if (parsed.type === "response.output_text.delta" && typeof parsed.delta === "string") onDelta(parsed.delta);
      else if (parsed.type === "response.completed") return;
      else if (typeof parsed.text === "string") onDelta(parsed.text);
    }
  }
}
